import React, { useEffect, useState } from "react";
import { useParams, useSearchParams } from "react-router-dom";
import api from "../api";
import ProductCard from "../components/ProductCard";

const GENDER_LABEL = { men: "Men", women: "Women", unisex: "Sportswear" };

export default function Shop() {
  const { gender } = useParams();
  const [searchParams, setSearchParams] = useSearchParams();
  const activeCategory = searchParams.get("category") || "";

  const [categories, setCategories] = useState([]);
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    api.get("/categories").then((res) => setCategories(res.data));
  }, []);

  useEffect(() => {
    setLoading(true);
    const params = { gender };
    if (activeCategory) params.category = activeCategory;

    api
      .get("/products", { params })
      .then((res) => setProducts(res.data))
      .finally(() => setLoading(false));
  }, [gender, activeCategory]);

  function selectCategory(slug) {
    if (slug) setSearchParams({ category: slug });
    else setSearchParams({});
  }

  return (
    <div className="container">
      <div className="filter-bar">
        <div>
          <h1 className="page-title">{GENDER_LABEL[gender] || "Shop"}</h1>
        </div>
        <div className="filter-pills">
          <button className={`pill ${!activeCategory ? "active" : ""}`} onClick={() => selectCategory("")}>
            All
          </button>
          {categories.map((c) => (
            <button
              key={c.id}
              className={`pill ${activeCategory === c.slug ? "active" : ""}`}
              onClick={() => selectCategory(c.slug)}
            >
              {c.name}
            </button>
          ))}
        </div>
      </div>

      {loading ? (
        <div className="empty-state">Loading...</div>
      ) : products.length === 0 ? (
        <div className="empty-state">No products found in this category yet.</div>
      ) : (
        <div className="product-grid">
          {products.map((p) => (
            <ProductCard key={p.id} product={p} />
          ))}
        </div>
      )}
    </div>
  );
}
